// Settings defines model for Settings.
type Settings struct {
	// AcmeDirectory ACME 目录地址。留空用生产环境。
	//
	// 测试环境（staging）签发的证书**不被浏览器信任**，但配额宽松
	// 得多 —— 首次配置时值得用它试一遍，因为生产环境的失败配额是
	// 每小时 5 次，调配置很容易把它用光。
	AcmeDirectory *string `json:"acme_directory,omitempty"`

	// AcmeDnsCredentialId 做 DNS-01 校验用的凭据 ID。
	//
	// 该凭据对应的服务商必须支持完整的记录管理（Tier-1 六家之一）——
	// DNS-01 需要在你的 DNS 里创建一条 TXT 记录。
	AcmeDnsCredentialId *string `json:"acme_dns_credential_id,omitempty"`

	// AcmeEmail ACME 账户的联系邮箱。
	//
	// 它很重要：证书快要过期而自动续期失败时，CA 会用它来提醒。
	// 不填会让"续期静默失败"变成"站点某天突然打不开"。
	AcmeEmail *string `json:"acme_email,omitempty"`

	// EventBufferSize 事件环形缓冲容量。调大可延长断线补发的覆盖窗口。
	EventBufferSize *int             `json:"event_buffer_size,omitempty"`
	Lang            SettingsLang     `json:"lang"`
	LogLevel        SettingsLogLevel `json:"log_level"`

	// NotifyOnIpChange 地址或 IPv6 前缀变化时是否发送通知。
	NotifyOnIpChange *bool `json:"notify_on_ip_change,omitempty"`

	// ProxyEnabled 是否启动反向代理。
	//
	// 默认**关闭**：反代监听在公网上，开启它是一个需要明确决定的
	// 动作。默认开着会让"我只是想用动态解析"的用户莫名其妙地多出
	// 一个对外的监听端口。
	ProxyEnabled *bool `json:"proxy_enabled,omitempty"`

	// ProxyPort 反向代理的监听端口。
	//
	// 默认 443 而不是 8080：用户访问的地址里不该带端口号，
	// 而 443 是浏览器默认补的那个。
	ProxyPort *int `json:"proxy_port,omitempty"`

	// ProxyTls 反向代理是否用 HTTPS 提供服务。
	//
	// 开启它需要同时配置 ACME（DNS-01 凭据），否则证书签不出来，
	// 而症状是"浏览器报证书错误"。
	ProxyTls *bool `json:"proxy_tls,omitempty"`

	// RemotePublicDomain 子域名挂在哪个域名下（用户选的），例如 `example.com`。
	//
	// 用户只回答这一个问题：哪把凭据、哪个区域由这个域名唯一决定，
	// 内核自己反查得出来。填错会一路走到"找不到区域"或者更糟 ——
	// 在**别的区域**里建了一条记录。
	RemotePublicDomain *string `json:"remote_public_domain,omitempty"`

	// RemotePublicEnabled 公网访问：在**用户自己的**域名下建一条随机子域名，用 AAAA
	// 指向本机的公网 IPv6，并给它签一张受信任的证书。
	//
	// 与 `remote_enabled` 分开而不是合并成一个开关，因为两者的
	// **代价**不同：局域网监听只在局域网内可见，而公网访问会把
	// 内核暴露在互联网上。
	RemotePublicEnabled *bool `json:"remote_public_enabled,omitempty"`

	// TunnelBinary cloudflared 的路径；留空则按常见位置自动寻找。
	//
	// 留这个入口是因为"找不到 cloudflared"是这条链路上最常见的
	// 一步卡住，而用户装在一个非常规位置时，直接指过去比去猜快。
	TunnelBinary *string `json:"tunnel_binary,omitempty"`

	// TunnelEnabled 是否用 Cloudflare 隧道发布站点。
	//
	// 它解决的是直连模型解决不了的那类网络：大内网（CGNAT）后的
	// 家宽、校园网、公司网 —— 入站连接在网关上就被丢掉了，本机
	// 怎么配都没用。隧道换方向：本机主动向 Cloudflare 建一条长
	// 连接，外面来的请求顺着它进来。
	//
	// 与 proxy_enabled 是**叠加**关系：隧道把流量送到本机反代上，
	// 因此两个要一起开。
	TunnelEnabled *bool `json:"tunnel_enabled,omitempty"`
}

